package com.nexusdrive.common.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter;
public class JwtAuthFilter extends OncePerRequestFilter { private final JwtTokenProvider jwt; public JwtAuthFilter(JwtTokenProvider j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.validate(t)&&"access".equals(jwt.parse(t).get("type",String.class))){var p=new CustomUserDetails(jwt.userId(t),jwt.parse(t).getSubject(),"",jwt.role(t),true);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,t,List.of(new SimpleGrantedAuthority("ROLE_"+p.role()))));}}c.doFilter(r,s);} }
